import{_ as t,o as r,c as n,ah as a}from"./chunks/framework.C-FRNfAJ.js";const p=JSON.parse('{"title":"Funding learners","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/entreprises/financeur.md","filePath":"src/en/guide/entreprises/financeur.md"}'),o={name:"en/guide/entreprises/financeur.md"};function i(s,e,d,h,l,u){return r(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="funding-learners" tabindex="-1">Funding learners <a class="header-anchor" href="#funding-learners" aria-label="Permalink to &quot;Funding learners&quot;">​</a></h1><p>A company or organization can take on all or part of a learner&#39;s training. The <strong>Funder</strong> role gives it a dedicated space, <strong>Journeys → Funded learners</strong>.</p><h2 id="getting-the-funder-role" tabindex="-1">Getting the Funder role <a class="header-anchor" href="#getting-the-funder-role" aria-label="Permalink to &quot;Getting the Funder role&quot;">​</a></h2><p>The role requires an <strong>organization account</strong>: if your account is an individual account, <a href="./../premiers-pas.html#individual-or-organization-account">convert it first</a>. Then ask for the <strong>Funder</strong> role in <strong>Settings → Roles</strong>. The request is examined by the Partnerships Officer, who tells you of their decision by e-mail.</p><h2 id="how-a-funding-starts" tabindex="-1">How a funding starts <a class="header-anchor" href="#how-a-funding-starts" aria-label="Permalink to &quot;How a funding starts&quot;">​</a></h2><p>The funding is decided <strong>with the learner, before their agreement is signed</strong>. The Pedagogical Coordinator designates your account as funder and sets your share, from 1 to 100%.</p><p>From then on:</p><ul><li>the <strong>split</strong> appears in the training agreement (for example 60% for the learner, 40% for you);</li><li>each instalment is invoiced in <strong>two separate invoices</strong>, one per payer, each followed separately;</li><li>if you fund 100%, the learner has nothing to pay.</li></ul><h2 id="your-funded-learners-space" tabindex="-1">Your &quot;Funded learners&quot; space <a class="header-anchor" href="#your-funded-learners-space" aria-label="Permalink to &quot;Your &quot;Funded learners&quot; space&quot;">​</a></h2><p>You see there <strong>only the learners you fund</strong>: their training, their cohort, their status and <strong>your share</strong>, as well as the <strong>invoices for your share</strong>. You see neither the other funders nor the learner&#39;s invoices.</p><p>Invoices are also sent to you as a PDF by e-mail, and filed in <strong>My documents</strong>.</p><h2 id="signing-the-tripartite-agreement" tabindex="-1">Signing the tripartite agreement <a class="header-anchor" href="#signing-the-tripartite-agreement" aria-label="Permalink to &quot;Signing the tripartite agreement&quot;">​</a></h2><p>When the learner&#39;s agreement is counter-signed by edPage group, a <strong>tripartite funding agreement</strong> is prepared for you. It repeats the terms of the agreement: the parties, the training, the cohort, the price, your share and the schedule.</p><p>To sign it, from <strong>Funded learners</strong>:</p><ol><li>open the learner&#39;s tripartite agreement;</li><li>scroll to the end and tick &quot;I have read the agreement to the end and accept its terms&quot;;</li><li>ask for the code: a <strong>6-digit</strong> code is sent to your e-mail address, valid <strong>15 minutes</strong>, usable once, with 5 tries;</li><li>enter it and sign.</li></ol><p>edPage group then counter-signs. The sealed PDF (<code>CONVT-NB-YYYY-XXX</code>) is sent to you and to the learner.</p><p>This agreement <strong>delays neither the enrolment nor billing</strong>: they already rest on the learner&#39;s agreement. If the learner changes cohort, the tripartite is replaced along with their agreement, and a new one is offered to you.</p><h2 id="late-payments" tabindex="-1">Late payments <a class="header-anchor" href="#late-payments" aria-label="Permalink to &quot;Late payments&quot;">​</a></h2><p>Reminders and the timeline of a non-payment are those of any invoice: reminders 15, 7 and 1 days before the due date, a reminder the next day, the Coordinator&#39;s follow-up at D+7, overdue and 15-day moratorium at D+15, suspension at D+30.</p><p><strong>If your share is late, the learner&#39;s access to Sève is suspended</strong>, even if they have paid theirs. It is restored as soon as you pay.</p><p>The training balance must be paid, by the learner <strong>and</strong> by you, for the certificate to be issued.</p>',21)])])}const c=t(o,[["render",i]]);export{p as __pageData,c as default};
